/**
 * Public face of the i18n module. The catalogues live in ./catalogue and the language list
 * in ./languages; this file wires them together and exposes translate().
 *
 * English is the source of truth and Hindi is complete. The other launch languages are
 * generated by `npm run translate:ui` into ./generated, and still need a native speaker's review.
 * Until that script has run, their files are empty. A key missing from a language falls back to
 * English; AI replies always use the worker's own language regardless.
 */
import { en, type MessageKey, type Messages } from "./catalogue/en";
import { HELPLINE_LABEL, hi } from "./catalogue/hi";
import { generated } from "./generated";
import { DEFAULT_LANG, LANGUAGES, isLangCode, type LangCode } from "./languages";

export { DEFAULT_LANG, HELPLINE_LABEL, LANGUAGES, en, hi, isLangCode };
export type { LangCode, MessageKey, Messages };

/** English and Hindi are hand-written and complete; the rest come from `npm run translate:ui`. */
const catalogues: Partial<Record<LangCode, Partial<Messages>>> = { ...generated, en, hi };

export function translate(lang: LangCode, key: MessageKey, vars?: Record<string, string | number>): string {
  const raw = catalogues[lang]?.[key] ?? en[key];
  if (!vars) return raw;
  return raw.replace(/\{(\w+)\}/g, (_, k: string) => String(vars[k] ?? `{${k}}`));
}

/** A language counts as having its own screens when nearly every string is translated, not just a few. */
const COMPLETE_SHARE = 0.95;

/**
 * Whether the screens are really in this language, or mostly English because its translation has not been
 * generated yet. The AI answers in the worker's language either way; this is only about the interface,
 * so the language picker can say so instead of looking broken.
 */
export function isInterfaceComplete(
  lang: LangCode,
  tables: Partial<Record<LangCode, Partial<Messages>>> = catalogues,
): boolean {
  if (lang === "en") return true;
  const keys = Object.keys(en);
  const have = keys.filter((k) => Boolean(tables[lang]?.[k as MessageKey])).length;
  return have / keys.length >= COMPLETE_SHARE;
}
